# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TEKLÎFÎ HÜKÜMLERİN ALT KISIMLARI (EF\'ÂL-İ MÜKELLEFÎN AYRINTILARI)</text>\n  <rect x="18" y="42" width="214" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Farzın Kısımları</text>\n  <text x="30" y="88" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Farz-ı Ayn:</text>\n  <text x="38" y="104" font-size="10.2" fill="#1e3a8a">Her mükellefin bizzat kendisinin</text>\n  <text x="38" y="119" font-size="10.2" fill="#1e3a8a">yapmakla yükümlü olduğu farzdır</text>\n  <text x="38" y="134" font-size="10.2" fill="#1e3a8a">(Beş vakit namaz, oruç, zekât).</text>\n  <text x="30" y="156" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Farz-ı Kifâye:</text>\n  <text x="38" y="172" font-size="10.2" fill="#1e3a8a">Bazı Müslümanların yapmasıyla</text>\n  <text x="38" y="187" font-size="10.2" fill="#1e3a8a">diğerlerinden sorumluluğun düştüğü</text>\n  <text x="38" y="202" font-size="10.2" fill="#1e3a8a">farzdır (Cenaze namazı, selam almak).</text>\n  <rect x="243" y="42" width="214" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Sünnetin Kısımları</text>\n  <text x="255" y="88" font-size="10.8" font-weight="bold" fill="#15803d">• Sünnet-i Müekkede:</text>\n  <text x="263" y="104" font-size="10.2" fill="#14532d">Hz. Peygamber\'in devamlı yaptığı,</text>\n  <text x="263" y="119" font-size="10.2" fill="#14532d">nadiren terk ettiği sünnettir (Sabah,</text>\n  <text x="263" y="134" font-size="10.2" fill="#14532d">öğle, akşam sünnetleri; cemaatle namaz).</text>\n  <text x="255" y="156" font-size="10.8" font-weight="bold" fill="#15803d">• Sünnet-i Gayr-i Müekkede:</text>\n  <text x="263" y="172" font-size="10.2" fill="#14532d">İbadet maksadıyla bazen yapıp bazen</text>\n  <text x="263" y="187" font-size="10.2" fill="#14532d">terk ettiği sünnet (İkindi ve yatsının</text>\n  <text x="263" y="202" font-size="10.2" fill="#14532d">ilk sünnetleri; mendup / müstehap).</text>\n  <rect x="468" y="42" width="214" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Haram ve Mekruhun Kısımları</text>\n  <text x="480" y="88" font-size="10.5" fill="#7f1d1d">• Haram Li-aynihî (Özündeki kötülük)</text>\n  <text x="480" y="104" font-size="10.5" fill="#7f1d1d">• Haram Li-gayrihî (Dış sebeple haram)</text>\n  <text x="480" y="128" font-size="10.8" font-weight="bold" fill="#b91c1c">• Tahrîmen Mekruh:</text>\n  <text x="488" y="144" font-size="10.2" fill="#7f1d1d">Harama yakın mekruh; zannî delille</text>\n  <text x="488" y="159" font-size="10.2" fill="#7f1d1d">kesin yasaklanan (Vacibin terki).</text>\n  <text x="480" y="179" font-size="10.8" font-weight="bold" fill="#b91c1c">• Tenzîhen Mekruh:</text>\n  <text x="488" y="195" font-size="10.2" fill="#7f1d1d">Helale yakın mekruh (Sünnetin terki).</text>\n  <rect x="18" y="224" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Farz-ı kifâyeyi toplumda hiç kimse yerine getirmezse o beldedeki bütün Müslümanlar sorumlu olur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VAZ\'Î HÜKÜMLER: SEBEP, RÜKÜN, ŞART VE MÂNİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">İBADETİN VARLIK VE KURULUŞ UNSURLARI</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#a16207">• Sebep (Vakit / Neden):</text>\n  <text x="44" y="105" font-size="10.5" fill="#713f12">Bulunduğunda hükmün var olmasına yol açan durum</text>\n  <text x="44" y="120" font-size="10.5" fill="#713f12">(Vaktin girmesi namazın, Ramazan ayı orucun sebebidir).</text>\n  <text x="34" y="142" font-size="11" font-weight="bold" fill="#a16207">• Şart (İbadetin Dışındaki Farzlar):</text>\n  <text x="44" y="159" font-size="10.5" fill="#713f12">İbadetin mahiyeti dışında olup başlangıçta bulunması</text>\n  <text x="44" y="174" font-size="10.5" fill="#713f12">zorunlu olan unsur (Abdest, setr-i avret, kıble).</text>\n  <text x="34" y="196" font-size="11" font-weight="bold" fill="#a16207">• Mâni (Engel): Hükmün doğmasını önleyen durum (Borç, hayız).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">RÜKÜN İLE ŞART ARASINDAKİ FARK (NAMAZ ÖRNEĞİ)</text>\n  <text x="370" y="88" font-size="11" font-weight="bold" fill="#7e22ce">• Rükün (İbadetin İçindeki Farzlar):</text>\n  <text x="380" y="105" font-size="10.5" fill="#581c87">İbadetin veya akdin bizzat kendi yapısını/mahiyetini</text>\n  <text x="380" y="120" font-size="10.5" fill="#581c87">oluşturan iç unsurlardır.</text>\n  <text x="370" y="144" font-size="10.8" fill="#581c87">• Namazın Şartları (Dışında - 6): Hadesten taharet,</text>\n  <text x="380" y="160" font-size="10.4" fill="#581c87">necasetten taharet, setr-i avret, istikbâl-i kıble, vakit, niyet.</text>\n  <text x="370" y="182" font-size="10.8" fill="#581c87">• Namazın Rükünleri (İçinde - 6): İftitah tekbiri, kıyam,</text>\n  <text x="380" y="198" font-size="10.4" fill="#581c87">kıraat, rükû, secde ve ka\'de-i ahîre (son oturuş).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir ibadetin hem şartları hem de rükünleri farzdır; biri eksik olursa ibadet geçerli (sahih) olmaz.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VAZ\'Î HÜKÜMLER: AZİMET - RUHSAT VE SIHHAT - BUTLAN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">AZİMET VE RUHSAT DENGESİ</text>\n  <text x="34" y="90" font-size="11" font-weight="bold" fill="#1d4ed8">• Azimet (Aslî ve Genel Hüküm):</text>\n  <text x="44" y="108" font-size="10.6" fill="#1e3a8a">Normal şartlarda bütün mükellefler için konulan</text>\n  <text x="44" y="124" font-size="10.6" fill="#1e3a8a">temel hükümdür (Suyla abdest almak, Ramazan\'da</text>\n  <text x="44" y="140" font-size="10.6" fill="#1e3a8a">oruç tutmak, öğle namazını 4 rekât farz kılmak).</text>\n  <text x="34" y="162" font-size="11" font-weight="bold" fill="#1d4ed8">• Ruhsat (Özre Bağlı Kolaylık Hükmü):</text>\n  <text x="44" y="180" font-size="10.6" fill="#1e3a8a">Hastalık, yolculuk, su yokluğu veya zaruret sebebiyle</text>\n  <text x="44" y="196" font-size="10.6" fill="#1e3a8a">tanınan kolaylıktır (Teyemmüm, seferîlikte 2 rekât).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SIHHAT (SAHİH) VE BUTLAN (BÂTIL / FÂSİD)</text>\n  <text x="370" y="90" font-size="11" font-weight="bold" fill="#c2410c">• Sahih (Sıhhat):</text>\n  <text x="380" y="108" font-size="10.6" fill="#7c2d12">Farz, vacip, şart ve rükünlerine tam uyularak</text>\n  <text x="380" y="124" font-size="10.6" fill="#7c2d12">yapılan ve hukuki sonuç doğuran geçerli fiildir.</text>\n  <text x="370" y="148" font-size="11" font-weight="bold" fill="#c2410c">• Bâtıl (Butlan) ve Fâsid:</text>\n  <text x="380" y="166" font-size="10.6" fill="#7c2d12">Şart veya rükünlerinden biri eksik olduğu için</text>\n  <text x="380" y="182" font-size="10.6" fill="#7c2d12">geçersiz sayılan, sorumluluğu düşürmeyen fiildir</text>\n  <text x="380" y="198" font-size="10.6" fill="#7c2d12">(Abdestsiz kılınan namaz bâtıldır, iadesi gerekir).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İbadetlerin vaktinde yapılmasına EDÂ, vakti çıktıktan sonra yapılmasına KAZÂ, bozulanın yeniden yapılmasına İÂDE denir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
